/**
 * W-M2e item 2 -- the REVIEWED list of server codes that use no Swedish text of their own in the LU UI,
 * each with its group (justification, below) and a note on where it lives and why the UI text it meets
 * is true for it. Read by tests/unit/luErrorCodeInventory.test.ts, which fails on a scanned code that is
 * neither here nor given its own text, on a stale entry, and on an entry whose group can be checked
 * mechanically and does not hold (outside the LU reach, a parent with its own text).
 *
 * Reviewed by W-M2e (2026-10-02) against the code at the time: the in-reach entries one by one (family
 * notes for the large REJECT_* families), the out-of-reach entries by the computed import closure.
 * A NEW code: give it a Swedish text in the UI if a user can meet it; otherwise add an entry here with the
 * group that is TRUE for it -- never to silence the test.
 */

export type LuFallbackGroup =
  | 'OUTSIDE_LU_REACH'
  | 'NOT_A_WIRE_CODE'
  | 'SERVER_INTERNAL'
  | 'RAW_MESSAGE_ONLY'
  | 'COVERED_BY_PARENT'
  | 'SERVER_TEXT_VERBATIM'
  | 'GENERIC_TEXT_EXACT'
  | 'NOT_PRESENTED';

export const LU_FALLBACK_GROUPS: Readonly<Record<LuFallbackGroup, string>> = {
  OUTSIDE_LU_REACH:
    'The token occurs only in modules OUTSIDE the static value-import closure of the LU routes and LU workers (computed by the test), so no answer the LU UI reads can carry it. Checked mechanically: the test fails if any file holding the token joins the LU reach.',
  NOT_A_WIRE_CODE:
    'The token is a name, not an error code: an environment variable, an artifact/contract/kind id, a worker id, a purpose. It never travels as code, failureClass, reasonCode, state or reason in an LU answer, so it needs no Swedish error text.',
  SERVER_INTERNAL:
    'Produced and consumed inside the server (a typed error identity, a fault reason kept server-side, a queue record, a log/diagnostic detail, a tool outside the LU request path). The LU answer carries instead a typed code/class with its own UI text, a status, or nothing.',
  RAW_MESSAGE_ONLY:
    'A token at the start of a thrown error message. It reaches an LU answer at most inside the raw `error` text (kept by the UI only under Teknisk information), as a reasonCode under a code with its own text, or not at all (sanitized 500, a failed run). The UI main text is then the code\'s own text or the neutral text of the HTTP status and context (W-M2e: the 409/424 texts claim no cause; the geometry 404 has its own neutral text).',
  COVERED_BY_PARENT:
    'Travels only as a reasonCode/failureClass (or fixed message) under a parent that has its own Swedish text describing this case fully. Checked mechanically: the parent must have its own text in the UI tables.',
  SERVER_TEXT_VERBATIM:
    'Travels together with the server\'s own Swedish text (message_sv, statement_sv, binding_note_sv, text_sv), which the UI shows verbatim by owner directive (W-M2d items 1-2: the server is the single source of check rows and the overall line); the code itself is shown only under Teknisk information.',
  GENERIC_TEXT_EXACT:
    'Reaches the UI, and the UI\'s general text at that place is exact for it (a failed or denied run\'s status line, verify\'s "N avvikelser" line); the code is listed under Teknisk information.',
  NOT_PRESENTED:
    'W-UI1: travels in an LU answer, but in a field the LU UI never renders as text (it is not read, or used only as a switch or key; checked in components/app/lu). No user meets the value, so no Swedish text is needed; if a later UI starts to show the field, the value needs its own text.',
};

export interface LuFallbackEntry {
  readonly group: LuFallbackGroup;
  readonly note: string;
  /** COVERED_BY_PARENT: the token with its own text (or `message:<LU_SERVER_MESSAGE key>`) that covers this one. */
  readonly parent?: string;
}

/**
 * W-UI1 (M2e verification finding 1, C5): every code-shaped TEMPLATE literal in the LU reach, with EVERY value it
 * can build. The expansions are inventoried like scanned codes (own text or a reviewed entry each). The test
 * fails on a template that is not listed here and on a listed one the code no longer builds.
 */
export interface LuReviewedTemplate {
  readonly file: string;
  readonly template: string;
  readonly expansions: readonly string[];
  readonly note: string;
}

